INSERT INTO "movies" VALUES(33,'Gentleman Thief 2026','gentleman-thief-2026','https://tv12.lk21official.cc/gentleman-thief-2026','6.2','https://cover.showcdnx.com/wp-content/uploads/2026/07/film-gentleman-thief-2026-lk21.jpg','movie','WEBDL','Action','Dalam film The Gentleman Thief, seorang mantan pencuri profesional terpaksa kembali ke dunianya yang penuh bahaya untuk melindungi adiknya yang impulsif dari bencana. Mereka terlibat dalam penyelundupan kapal mewah senilai $100M yang berujung pada jaringan penipuan berbahaya. Musuh lama muncul kembali, memaksa dia menggunakan semua triknya untuk tetap hidup.','John Travolta,Lukas Haas,Rebecca De Mornay,Tim Sitarz,Sam Asghari','https://videonode.de/iframe/p2p/JR0nOikcGiAsfAMkKlUwdXBIe3hoLjIDBh0oFBxRN2h1Gngqdg','https://playcdn.de/xxx/JR0nOikcGiAsfAMkKlUwdXBIe3hoLjIDBh0oFBxRN2h1Gngqdg8492e8e6/43/480.m3u8','2026-08-09 15:49:35');
