INSERT INTO "movies" VALUES(67,'Swapped 2026','swapped-2026','https://tv12.lk21official.cc/swapped-2026','8.8','https://cover.showcdnx.com/wp-content/uploads/2026/05/film-swapped-2026-lk21.jpg','movie','WEBDL','Animation,Adventure','Dalam film "Swapped" (2026), seekor makhluk hutan kecil dan burung megah tiba-tiba bertukar tubuh, memaksa mereka bekerja sama untuk bertahan hidup dalam petualangan paling liar mereka. Dengan kekuatan dan kemampuan baru, mereka harus beradaptasi dan belajar dari satu sama lain untuk kembali ke tubuh asli mereka.','Camden Brooks,Joan Ryan','https://videonode.de/iframe/p2p/MQ8oPjUcE2xwYUV6bmcTGgY0FhYaHEJwemNEfnM','https://playcdn.de/xxx/MQ8oPjUcE2xwYUV6bmcTGgY0FhYaHEJwemNEfnM8492e8e6/41/480.m3u8','2026-08-09 15:50:04');
