INSERT INTO "movies" VALUES(72,'Hoppers 2026','hoppers-2026','https://tv12.lk21official.cc/hoppers-2026','8.1','https://cover.showcdnx.com/wp-content/uploads/2026/03/film-hoppers-2026-lk21.jpg','movie','BLURAY','Animation,Adventure','"Hoppers" (2026) mengisahkan seorang pecinta hewan berusia 19 tahun yang menggunakan teknologi canggih untuk memindahkan kesadaran vao tubuh kelinci robotik. Dalam petualangan epik ini, ia menemukan dunia hewan yang penuh misteri dan keajaiban, membuka pintu menuju petualangan tak terbayangkan. Dengan tawa dan aksi yang tak terduga, "Hoppers" menawarkan pengalaman menarik bagi seluruh keluarga, menggabungkan komedi, petualangan, dan ilmu pengetahuan dalam satu kesatuan menyenangkan.','Bobby Moynihan,Piper Curda,Kathy Najimy,Jon Hamm,Dave Franco,Eduardo Franco,Nichole Sakura,Meryl Streep,Isiah Whitlock Jr.,Vanessa Bayer','https://videonode.de/iframe/p2p/Khc5PiALBGxwYUV6bnI6LRAZMBEdJkN1cWYUfSUH','https://playcdn.de/xxx/Khc5PiALBGxwYUV6bnI6LRAZMBEdJkN1cWYUfSUH8492e8e6/41/480.m3u8','2026-08-09 15:50:09');
