INSERT INTO "movies" VALUES(98,'Guardians Of The Galaxy Vol 3 2023','guardians-of-the-galaxy-vol-3-2023','https://tv12.lk21official.cc/guardians-of-the-galaxy-vol-3-2023','7.9','https://cover.showcdnx.com/wp-content/uploads/2023/05/film-guardians-of-the-galaxy-vol-3-2023-lk21-d21.jpg','movie','BLURAY','Comedy,Action','Peter Quill masih berduka kehilangan Gamora, tapi ancaman baru memaksa Guardians bertarung sekali lagi—untuk menyelamatkan alam semesta dan salah satu dari mereka. Misi ini bisa jadi yang terakhir jika gagal. Dengan aksi spektakuler, komedi khas, dan soundtrack epik, petualangan terakhir tim paling kacau di galaksi ini akan menghancurkan—dan menyatukan—hati penonton! Budget $250 juta, hasil box office $845 juta, dan lagu "Creep" versi akustik yang menyentuh jiwa.','Bradley Cooper,Chris Pratt,Chukwudi Iwuji','https://videonode.de/iframe/p2p/d67e79ec9b38c7f0606c199d21506aad','https://playcdn.de/xxx/d67e79ec9b38c7f0606c199d21506aad8492e8e6/31/480.m3u8','2026-08-09 15:50:32');
