DROP TABLE IF EXISTS movies;
CREATE TABLE movies (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            slug TEXT UNIQUE,
            url TEXT,
            rating TEXT,
            poster_image TEXT,
            type TEXT,
            quality TEXT,
            genres TEXT,
            synopsis TEXT,
            cast TEXT,
            iframe_url TEXT,
            stream_url TEXT,
            created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
        );
